# >>> STATIC
_static_sidtype_type() {
    cat <<-'ARGCEOF'
	none	If this setting is "none", the SCM will not add the service's SID to the service process token
	unrestricted	If this setting is "unrestricted", the Service Control Manager (SCM) will add this service's SID to the service process token when the service process starts the next time due to the first service in the process being started
	restricted	If this setting is "restricted", the Service Control Manager (SCM) will add this service's SID to the service process token when the service process starts the next time due to the first service in the process being started
ARGCEOF
}

_static_managedaccount_type() {
    cat <<-'ARGCEOF'
	true	If this setting is "true", the Service Control Manager (SCM) will request the account password from NetLogon when starting the service
	false	If this setting is "false", the SCM will use the configured account password
ARGCEOF
}
