if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_sc_control() {
    printf '%s\n' paramchange netbindadd netbindremove netbindenable netbinddisable
}

_choice_sc_display_name() {
    sc query state= all 2>/dev/null | sed -n 's/^DISPLAY_NAME: //p' | head -n 500
}

_choice_sc_service() {
    sc query state= all 2>/dev/null | sed -n 's/^SERVICE_NAME: //p' | head -n 500
}
